{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/dish-compare.json
    Grill cuts side by side: an accessible table (caption, column and row headers) of the cut, weight, cooking time, heat, marinade and price, or one compare card per cut with the same facts as a description list. Axes: layout (table, cards), tone.
    Props (p): id, title, lead, dishes, empty, labels, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_dishes = ($p['dishes'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'table')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_20}
  {if og_t(og_eq(og_len($v_dishes), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'scale', 'title' => $v_empty]])|noescape}
  {elseif og_t(og_eq($v_layout, 'table'))}
    {capture $c_19}
      {capture $c_18}
        {capture $c_1}
          {=og_text(og_get($v_labels, ['caption']))}
        {/capture}
        {=og_include('compose/TableCaption.latte', ['class' => 'sr-only', 'children' => (string) $c_1])|noescape}
        {capture $c_9}
          {capture $c_8}
            {capture $c_2}
              {=og_text(og_get($v_labels, ['cut']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_2])|noescape}
            {capture $c_3}
              {=og_text(og_get($v_labels, ['weight']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_3])|noescape}
            {capture $c_4}
              {=og_text(og_get($v_labels, ['minutes']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_4])|noescape}
            {capture $c_5}
              {=og_text(og_get($v_labels, ['heat']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_5])|noescape}
            {capture $c_6}
              {=og_text(og_get($v_labels, ['marinade']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_6])|noescape}
            {capture $c_7}
              {=og_text(og_get($v_labels, ['price']))}
            {/capture}
            {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2', 'attrs' => og_attrs(['scope', 'col']), 'children' => (string) $c_7])|noescape}
          {/capture}
          {=og_include('compose/TableRow.latte', ['children' => (string) $c_8])|noescape}
        {/capture}
        {=og_include('compose/TableHead.latte', ['children' => (string) $c_9])|noescape}
        {capture $c_17}
          {foreach og_l($v_dishes) as $v_d}
            {capture $c_16}
              {capture $c_10}
                {=og_text(og_get($v_d, ['name']))}
              {/capture}
              {=og_include('compose/TableHeadCell.latte', ['class' => 'py-2 font-semibold', 'attrs' => og_attrs(['scope', 'row']), 'children' => (string) $c_10])|noescape}
              {capture $c_11}
                {=og_text(og_get($v_d, ['weight']))}
              {/capture}
              {=og_include('compose/TableCell.latte', ['children' => (string) $c_11])|noescape}
              {capture $c_12}
                {=og_text(og_tpl(og_get($v_labels, ['minutes']), [og_str(og_get($v_d, ['minutes']))]))}
              {/capture}
              {=og_include('compose/TableCell.latte', ['children' => (string) $c_12])|noescape}
              {capture $c_13}
                {=og_text(og_get($v_d, ['tag']))}
              {/capture}
              {=og_include('compose/TableCell.latte', ['children' => (string) $c_13])|noescape}
              {capture $c_14}
                {foreach og_l(og_get($v_d, ['items'])) as $v_x}
                  {=og_text($v_x)}
                {/foreach}
              {/capture}
              {=og_include('compose/TableCell.latte', ['children' => (string) $c_14])|noescape}
              {capture $c_15}
                {=og_text(og_money(og_get($v_d, ['price']), og_get($v_d, ['currency'])))}
              {/capture}
              {=og_include('compose/TableCell.latte', ['class' => 'font-semibold', 'children' => (string) $c_15])|noescape}
            {/capture}
            {=og_include('compose/TableRow.latte', ['attrs' => og_attrs(['data-slot', 'item']), 'children' => (string) $c_16])|noescape}
          {/foreach}
        {/capture}
        {=og_include('compose/TableBody.latte', ['children' => (string) $c_17])|noescape}
      {/capture}
      {=og_include('compose/Table.latte', ['class' => 'w-full text-sm', 'children' => (string) $c_18])|noescape}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => 'w-full overflow-x-auto', 'attrs' => og_attrs(['data-slot', 'compare-table']), 'children' => (string) $c_19])|noescape}
  {else}
    {=og_include('blocks/cut-cards.latte', ['p' => ['dishes' => $v_dishes, 'labels' => $v_labels]])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_20)])|noescape}
